/** Generated from the overhaul textbook. Re-run tools/import-overhaul-courses.mjs. Do not edit by hand. */
export default {"id":"launchkey-level-15","number":15,"title":"Novation Components Custom Mode Authoring","skillBand":"Textbook","duration":"From the course textbook","summary":"Custom Modes allow users to completely reconfigure the MIDI output, continuous controllers, button actions, and visual color telemetry of the Launchkey MK4 61 using the Novation Components editor. On the 61-key chassis, Custom Modes operate","modules":[{"id":"launchkey-m-15-1-1","code":"15.1","title":"Novation Components Custom Mode Authoring","blurb":"Custom Modes allow users to completely reconfigure the MIDI output, continuous controllers, button actions, and visual color telemetry of the Launchkey MK4 61 using the Novation Components editor. On the 61-key chassis, Custom Modes operate","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-46","title":"Section overview","blocks":[{"type":"step","title":"Section 15.1 — The Custom Mode Architecture","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"Custom Modes allow users to completely reconfigure the MIDI output, continuous controllers, button actions, and visual color telemetry of the Launchkey MK4 61 using the Novation Components editor. On the 61-key chassis, Custom Modes operate across three discrete physical planes—Encoders, Pads, and Faders/Buttons—with four independent slots per plane."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Formulate the three independent Custom Mode hardware planes on the Launchkey MK4 61.","Recall Custom Modes on the hardware using dedicated Shift combinations.","Apply the 16-character alphanumeric label limit for OLED display feedback.","Formulate the operational scope of the <code>Encoders Curve</code> parameter in Custom Modes.","Execute local and cloud preset backup routines in Novation Components."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-15-1-1","title":"15.1.1: The Three Independent Custom Planes","blocks":[{"type":"step","title":"15.1.1: The Three Independent Custom Planes","blocks":[{"type":"prose","html":"Unlike smaller models, the Launchkey MK4 61 provides three discrete, independently selectable Custom Mode planes:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    LAUNCHKEY MK4 61 CUSTOM MODE PLANES                        |\n+-------------------+-----------------+-------------------+---------------------+\n| Custom Plane      | Number of Slots | Recall Shortcut   | Physical Hardware   |\n+-------------------+-----------------+-------------------+---------------------+\n| **Encoders**      | **4 Slots**     | `Shift + Pads 5–8`| 8 continuous pots   |\n|                   | (Custom 1–4)    |                   | (2 Pages = 16 CCs)  |\n+-------------------+-----------------+-------------------+---------------------+\n| **Pads**          | **4 Slots**     | `Shift + Pads 13–16`| 16 RGB velocity   |\n|                   | (Custom 1–4)    |                   | &amp; pressure pads     |\n+-------------------+-----------------+-------------------+---------------------+\n| **Faders &amp;**      | **4 Slots**     | `Shift + Fader    | 9 linear faders     |\n| **Buttons**       | (Custom 1–4)    |  Buttons 2–5`     | + 9 fader buttons   |\n+-------------------+-----------------+-------------------+---------------------+</pre>"},{"type":"prose","html":"<em>Auxiliary Custom Tabs</em>: Novation Components also provides dedicated programming tabs for the physical <strong>Sustain Pedal</strong> and <strong>Modulation Wheel</strong>."}]}],"minutes":8},{"id":"launchkey-l-15-1-2","title":"15.1.2: Hardware Mode Recall Protocol","blocks":[{"type":"step","title":"15.1.2: Hardware Mode Recall Protocol","blocks":[{"type":"prose","html":"Custom Modes can be recalled independently on each plane:"},{"type":"list","items":["To switch Encoders to Custom 2 without changing Pads: Hold <code>Shift</code> and press <strong>Pad 6</strong>.","To switch Pads to Custom 3: Hold <code>Shift</code> and press <strong>Pad 15</strong>.","To switch Faders to Custom 1: Hold <code>Shift</code> and press <strong>Fader Button 2</strong>.","<em>Components Direct Send</em>: Clicking \"Send to Launchkey\" inside Components automatically transfers and activates the newly authored mode on the hardware."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-15-1-3","title":"15.1.3: OLED 16-Character Alphanumeric Labels","blocks":[{"type":"step","title":"15.1.3: OLED 16-Character Alphanumeric Labels","blocks":[{"type":"prose","html":"In Components, every encoder, fader, pad, and button can be given a custom name:"},{"type":"list","items":["<strong>Character Constraint</strong>: Labels must not exceed <strong>16 characters</strong> (e.g., <code>Filter Cutoff</code>, <code>Decay Time</code>, <code>Verb Send</code>).","<strong>Default Behavior</strong>: If a control is left unnamed, the OLED screen displays the raw MIDI destination (e.g., <code>CC 21 (Ch 1)</code>)."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-15-1-4","title":"15.1.4: Encoder Curve Acceleration Scope","blocks":[{"type":"step","title":"15.1.4: Encoder Curve Acceleration Scope","blocks":[{"type":"list","items":["In Settings -&gt; <code>Encoders Curve</code> (Slow / Medium / Fast):","<strong>Operational Scope</strong>: This setting governs acceleration <strong>strictly when the continuous encoders are operating in Custom Modes 1–4</strong>. It has zero effect on DAW Plugin or Mixer modes."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-15-1-5","title":"15.1.5: Local & Cloud Preset Backup","blocks":[{"type":"step","title":"15.1.5: Local & Cloud Preset Backup","blocks":[{"type":"list","items":["<strong>Local Files</strong>: Custom modes can be exported as <code>.syx</code> or <code>.json</code> files to local storage without logging into an account.","<strong>Novation Cloud Account</strong>: Logging into Components allows saving custom templates directly to the user's account for instant recall on any workstation."],"ordered":false}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: 3 custom planes (Encoders, Pads, Faders/Buttons) with 4 slots each; recall commands (<code>Shift+Pads 5–8</code>, <code>Shift+Pads 13–16</code>, <code>Shift+Fader 2–5</code>); 16-character label limit; Encoder curve scope; local and cloud backup.","<strong>mustNotCover</strong>: Claiming 25/37 models possess the Fader Custom Mode plane."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task</strong>: Open Novation Components. In Custom Mode 1 (Encoders), name Encoder 1 <code>Resonance</code> and assign it to MIDI CC 71 on Channel 1. Send the mode to the Launchkey. Verify on the hardware OLED screen that turning Encoder 1 displays <code>Resonance: [Value]</code>."},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["Hardware recalls Custom 1 on the encoders via <code>Shift + Pad 5</code>.","Turning Encoder 1 displays the exact 16-character label <code>Resonance</code>.","MIDI output confirms CC 71 transmission on Channel 1."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-15-2-2","code":"15.2","title":"Novation Components Custom Mode Authoring","blurb":"Novation Components provides granular parameter assignment for the 8 continuous rotary encoders and 9 linear faders on the Launchkey MK4 61. This module covers supported MIDI message types, 7-bit versus 14-bit high-resolution data streams, ","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-47","title":"Section overview","blocks":[{"type":"step","title":"Section 15.2 — Custom Continuous Encoders & Linear Faders","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"Novation Components provides granular parameter assignment for the 8 continuous rotary encoders and 9 linear faders on the Launchkey MK4 61. This module covers supported MIDI message types, 7-bit versus 14-bit high-resolution data streams, two-page encoder banking, and fader button command mapping."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Program continuous encoders with 7-bit and 14-bit CC or NRPN messages.","Structure 16 discrete rotary controls across Page 1 and Page 2 in Novation Components.","Program linear faders with custom CC/NRPN ranges and select pickup takeover behaviors.","Program fader buttons across Note, CC, Program Change, NRPN, and Keystroke commands."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-15-2-1","title":"15.2.1: Continuous Encoder Configuration","blocks":[{"type":"step","title":"15.2.1: Continuous Encoder Configuration","blocks":[{"type":"prose","html":"In Novation Components, each rotary encoder can be independently programmed with the following parameters:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    CUSTOM ENCODER PARAMETER MATRIX                            |\n+-------------------+-----------------------------------------------------------+\n| Parameter Name    | Permitted Values / Options                                |\n+-------------------+-----------------------------------------------------------+\n| **Message Type**  | **Control Change (CC)**, **NRPN**, or **Off**             |\n|                   | *(Note messages are NOT supported on encoders)*           |\n+-------------------+-----------------------------------------------------------+\n| **Resolution**    | **7-bit** (0–127) or **14-bit** (High-Res 0–16383)        |\n+-------------------+-----------------------------------------------------------+\n| **CC / NRPN #**   | CC 0–127 / NRPN Parameter MSB &amp; LSB                       |\n+-------------------+-----------------------------------------------------------+\n| **Min / Max**     | Scaling range (e.g., 0–127, or inverted 127–0)            |\n+-------------------+-----------------------------------------------------------+\n| **MIDI Channel**  | Discrete Channels **1–16**, or **Global** (follows Part A)|\n+-------------------+-----------------------------------------------------------+</pre>"}]}],"minutes":8},{"id":"launchkey-l-15-2-2","title":"15.2.2: Two-Page Encoder Banking","blocks":[{"type":"step","title":"15.2.2: Two-Page Encoder Banking","blocks":[{"type":"prose","html":"Each Custom Encoder slot contains <strong>16 programmable controls</strong> split into two 8-encoder pages:"},{"type":"list","items":["<strong>Page 1 (Controls 1–8)</strong>: <code>Encoder Bank Down</code> LED is unlit; <code>Encoder Bank Up</code> is illuminated.","<strong>Page 2 (Controls 9–16)</strong>: <code>Encoder Bank Up</code> LED is unlit; <code>Encoder Bank Down</code> is illuminated.","Tapping the lit Bank button toggles cleanly between Page 1 and Page 2."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-15-2-3","title":"15.2.3: Custom Linear Faders Configuration","blocks":[{"type":"step","title":"15.2.3: Custom Linear Faders Configuration","blocks":[{"type":"prose","html":"All 9 physical faders can be customized in Components:"},{"type":"list","items":["<strong>Message Types</strong>: <strong>CC</strong>, <strong>NRPN</strong>, or <strong>Off</strong> (7-bit or 14-bit resolution).","<strong>Min / Max Boundaries</strong>: Custom output scaling (e.g., clamping a filter fader between CC values 30 and 100).","<strong>Pickup Takeover Behavior</strong>:","<em>Jump</em>: Hardware position snaps software parameter immediately.","<em>Pickup</em>: Waits until physical fader crosses software value.","<em>Settings Default</em>: Follows the global hardware Setting."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-15-2-4","title":"15.2.4: Custom Fader Buttons Programming","blocks":[{"type":"step","title":"15.2.4: Custom Fader Buttons Programming","blocks":[{"type":"prose","html":"The 9 tactile fader buttons beneath the faders operate as assignable multi-format triggers:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    CUSTOM FADER BUTTON MESSAGE TYPES                          |\n+-------------------+-----------------------------------------------------------+\n| Message Type      | Operational Functionality                                 |\n+-------------------+-----------------------------------------------------------+\n| **MIDI Note**     | Sends Note On/Off with programmable Velocity (1–127)      |\n| **Control Change**| Sends binary CC values (e.g., 0 / 127 or custom On/Off)   |\n| **Program Change**| Sends Program Change patch index (0–127)                  |\n| **NRPN**          | Sends discrete non-registered parameter triggers          |\n| **Keystroke**     | Injects operating system keyboard shortcuts (Section 15.3) |\n| **Off**           | Disables button output                                    |\n+-------------------+-----------------------------------------------------------+</pre>"},{"type":"list","items":["<strong>Behavior Mode</strong>: Configurable as <strong>Momentary</strong> (On while held, Off on release) or <strong>Toggle</strong> (alternates On/Off per press)."],"ordered":false}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Encoder parameters (CC/NRPN, 7/14-bit, Min/Max, Channel, 2 pages); Fader parameters (CC/NRPN, Pickup type); Fader Button parameters (Note, CC, Prog Change, NRPN, Keystroke, Momentary/Toggle).","<strong>mustNotCover</strong>: Assigning MIDI Note messages to continuous rotary encoders (unsupported in hardware)."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task</strong>: In Components, build a Custom Fader mode where Faders 1–8 send CCs 21–28 on Channel 1, Fader 9 sends Master CC 7, and Fader Button 1 sends a Momentary Note C3 on Channel 10. Send the mode to the Launchkey."},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["Faders 1–8 transmit CC 21–28 in a MIDI monitor.","Fader Button 1 transmits Note C3 on Channel 10 when pressed and Note Off when released."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-15-3-3","code":"15.3","title":"Novation Components Custom Mode Authoring","blurb":"The 16 RGB velocity-sensitive pads, rear sustain pedal jack, and physical modulation wheel can be fully customized within Novation Components. Additionally, the Launchkey MK4 61 includes hardware-level Computer Keystroke injection, allowing","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-48","title":"Section overview","blocks":[{"type":"step","title":"Section 15.3 — Custom RGB Pads, Pedal, Mod Wheel & Keystroke Macros","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"The 16 RGB velocity-sensitive pads, rear sustain pedal jack, and physical modulation wheel can be fully customized within Novation Components. Additionally, the Launchkey MK4 61 includes hardware-level <strong>Computer Keystroke injection</strong>, allowing pads and fader buttons to execute OS-level keyboard shortcuts. This module details pad configuration, pedal/wheel reassignment, keystroke macro mapping, and the critical Channel 16 standalone reservation warning."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Configure custom RGB pad assignments across MIDI Note, CC, Program Change, NRPN, and Keystroke commands.","Program custom dual-state RGB pad color illumination (On/Off states).","Reassign the rear Sustain Pedal and physical Modulation Wheel parameters in Components.","Program hardware-injected Computer Keystrokes for operating system and DAW workflow shortcuts.","Formulate the technical rationale for avoiding MIDI Channel 16 in custom mappings."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-15-3-1","title":"15.3.1: Custom RGB Pad Configuration","blocks":[{"type":"step","title":"15.3.1: Custom RGB Pad Configuration","blocks":[{"type":"prose","html":"In Components -&gt; <code>Pads</code> Custom Mode editor:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                      CUSTOM RGB PAD PARAMETER MATRIX                          |\n+-------------------+-----------------------------------------------------------+\n| Parameter Name    | Permitted Values / Options                                |\n+-------------------+-----------------------------------------------------------+\n| **Message Type**  | **Note**, **CC**, **Program Change**, **NRPN**, **Keystroke|\n+-------------------+-----------------------------------------------------------+\n| **RGB Palette**   | Independent **On Color** and **Off Color** (Full RGB)     |\n+-------------------+-----------------------------------------------------------+\n| **Behavior**      | **Momentary** (Active while held) or **Toggle** (Latching)|\n+-------------------+-----------------------------------------------------------+\n| **MIDI Channel**  | Discrete Channels **1–16**, or **Global**                 |\n+-------------------+-----------------------------------------------------------+</pre>"}]}],"minutes":8},{"id":"launchkey-l-15-3-2","title":"15.3.2: Custom Pedal & Mod Wheel Configuration","blocks":[{"type":"step","title":"15.3.2: Custom Pedal & Mod Wheel Configuration","blocks":[{"type":"list","items":["<strong><code>Pedal</code> Tab</strong>:","Factory Default: <strong>MIDI CC 64</strong> (Sustain).","Re-assignable to: Custom CCs (e.g., CC 11 Expression, CC 67 Soft Pedal), discrete MIDI Notes (e.g., triggering a foot-operated crash cymbal or vocal punch), or NRPNs.","<strong><code>Mod Wheel</code> Tab</strong>:","Factory Default: <strong>MIDI CC 1</strong> (Modulation).","Re-assignable to: Any 7-bit or 14-bit CC or NRPN with custom Min/Max scaling boundaries (e.g., scaling 0–100% travel to output strictly CC 74 between values 40 and 90)."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-15-3-3","title":"15.3.3: Computer Keystroke Macro Injection","blocks":[{"type":"step","title":"15.3.3: Computer Keystroke Macro Injection","blocks":[{"type":"prose","html":"The Launchkey MK4 61 microcontroller can enumerate as an auxiliary USB Human Interface Device (HID) keyboard to inject computer keystrokes directly into the host operating system:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    KEYSTROKE MACRO ASSIGNMENT EXAMPLES                        |\n+-------------------+---------------------------+-------------------------------+\n| Target Workflow   | Windows Keystroke Mapping | macOS Keystroke Mapping       |\n+-------------------+---------------------------+-------------------------------+\n| **Save Project**  | `Ctrl + S`                | `Cmd + S`                     |\n| **Split Clip**    | `Ctrl + E`                | `Cmd + E`                     |\n| **Duplicate**     | `Ctrl + D`                | `Cmd + D`                     |\n| **Export Audio**  | `Ctrl + Shift + R`        | `Cmd + Shift + R`             |\n+-------------------+---------------------------+-------------------------------+</pre>"},{"type":"prose","html":"<em>OS Shortcut Selection Rule</em>: When authoring Keystroke pads in Components, select the modifier key matching your active workstation OS (<code>Ctrl</code> for Windows, <code>Cmd</code> for macOS)."}]}],"minutes":8},{"id":"launchkey-l-15-3-4","title":"15.3.4: MIDI Channel 16 Standalone Reservation Warning","blocks":[{"type":"step","title":"15.3.4: MIDI Channel 16 Standalone Reservation Warning","blocks":[{"type":"prose","html":"Novation’s official Programmer's Reference establishes that in <strong>Standalone Mode</strong>, certain top-panel DAW transport and workflow buttons transmit control change messages on <strong>MIDI Channel 16</strong>."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------+\n|                  CHANNEL 16 RESERVATION WARNING                         |\n|                                                                         |\n|  Because Channel 16 is utilized by internal firmware for standalone    |\n|  hardware telemetry, assigning Custom Mode pads, encoders, or faders to |\n|  MIDI Channel 16 can create unpredictable command collisions.           |\n|                                                                         |\n|  BEST PRACTICE DIRECTIVE:                                               |\n|  Restrict all user Custom Modes to MIDI Channels 1 through 15.          |\n+-------------------------------------------------------------------------+</pre>"}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Pad parameters and dual RGB colors; Pedal CC/Note/NRPN; Mod Wheel scaling; Computer Keystrokes (Windows Ctrl vs Mac Cmd); Channel 16 standalone reservation warning.","<strong>mustNotCover</strong>: Speculation regarding multi-key text macro scripting beyond standard shortcut combinations."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task</strong>: In Components, program Pad 1 in Custom Mode 1 to transmit a <code>Ctrl + S</code> (Windows) or <code>Cmd + S</code> (macOS) Keystroke, with an Off Color of Dim Blue and an On Color of Bright Green. Send the mode to the Launchkey and test in your DAW."},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["Pressing Pad 1 executes project save in the DAW.","Pad illuminates Dim Blue at rest and flashes Bright Green when pressed."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-15-4-4","code":"15.4","title":"Novation Components Custom Mode Authoring","blurb":"Novation provides pre-configured factory Custom Mode templates within Components designed to control specific hardware and software synthesizers (e.g., GForce Bass Station VST, Xfer Records Serum, Native Instruments Komplete Kontrol / NKS).","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-49","title":"Section overview","blocks":[{"type":"step","title":"Section 15.4 — Factory Custom Templates & Third-Party Instruments","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"Novation provides pre-configured factory Custom Mode templates within Components designed to control specific hardware and software synthesizers (e.g., GForce Bass Station VST, Xfer Records Serum, Native Instruments Komplete Kontrol / NKS). This module documents these optional factory templates while enforcing the strict curriculum rule regarding software ownership boundaries."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Locate official Novation factory Custom Mode templates in Components.","Formulate the control mapping structure for the GForce Novation Bass Station plugin.","Formulate the control mapping structure for Xfer Serum custom profiles.","Formulate the Native Instruments NKS / Komplete Kontrol integration profile.","Apply the curriculum omission and gap-documentation policy for unowned third-party plugins."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-15-4-1","title":"15.4.1: GForce Novation Bass Station VST Template","blocks":[{"type":"step","title":"15.4.1: GForce Novation Bass Station VST Template","blocks":[{"type":"prose","html":"Novation publishes an official Custom Mode template for the GForce Bass Station software synthesizer:"},{"type":"list","items":["<strong>Encoders (Page 1 &amp; 2)</strong>: Mapped to Oscillator 1/2 Waveform, Pulse Width, Sub-Oscillator Level, Filter Cutoff, Resonance, and Mod Envelope Attack/Decay.","<strong>Faders 1–8</strong>: Mapped to the dedicated ADSR Amp and Mod Envelope sliders."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-15-4-2","title":"15.4.2: Xfer Records Serum Template","blocks":[{"type":"step","title":"15.4.2: Xfer Records Serum Template","blocks":[{"type":"prose","html":"The official Novation Serum template maps the Launchkey MK4 hardware controls to core wavetable parameters:"},{"type":"list","items":["<strong>Encoders</strong>: Mapped to Macro 1–4, Wavetable Position (Osc A/B), Warp Amount, and Master Filter Cutoff.","<strong>Faders</strong>: Mapped to FX parameters and Master Volume."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-15-4-3","title":"15.4.3: Native Instruments NKS / Komplete Kontrol Profile","blocks":[{"type":"step","title":"15.4.3: Native Instruments NKS / Komplete Kontrol Profile","blocks":[{"type":"prose","html":"Novation Components includes a standardized NKS template that maps Encoders 1–8 to the 8 standard NKS parameter pages utilized by Native Instruments Komplete Kontrol."}]}],"minutes":8},{"id":"launchkey-l-15-4-4","title":"15.4.4: The Strict Software Ownership & Gap Policy","blocks":[{"type":"step","title":"15.4.4: The Strict Software Ownership & Gap Policy","blocks":[{"type":"prose","html":"To preserve the technical integrity of this curriculum:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------+\n|                  THIRD-PARTY PLUGIN OWNERSHIP DIRECTIVE                 |\n|                                                                         |\n|  1. Third-party virtual instruments (e.g., Serum, Komplete Kontrol)     |\n|     are NOT part of Ableton Live 12 Standard or the Launchkey hardware. |\n|                                                                         |\n|  2. If a student does not own a specific third-party plugin:            |\n|     - Skip the specific plugin lesson.                                  |\n|     - Record a documented gap note: {type: 'unowned_plugin'}.           |\n|     - DO NOT substitute speculative or guessed parameter mappings.      |\n+-------------------------------------------------------------------------+</pre>"}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Official Novation template names (Bass Station VST, Serum, Komplete Kontrol/NKS); strict ownership rule; gap documentation policy.","<strong>mustNotCover</strong>: Teaching third-party plugins as if they were built into Live 12 Standard."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task</strong>: In Components, open the Template Library. If you own the GForce Bass Station or Serum plugin, load the official template into Custom Mode 4 and verify parameter tracking. If neither plugin is installed, record a written gap note confirming the ownership gate."},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["Template successfully loaded or skipped with documented ownership justification."],"ordered":false}]}],"minutes":8}],"exercises":[]}]};
